cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 13:00-14:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02 2>/dev/null)" ] || { echo "list --room with date printed a non-matching booking"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); rc=$?
[ $rc = 2 ] && [ "$out" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value: rc=$rc msg=$out"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null); rc=$?
[ $rc = 2 ] && [ "$out" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date: rc=$rc msg=$out"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/dev/null)" ] || { echo "list bad date printed to stdout"; fail=1; }
rm -f "$t"; exit $fail
EOF
sed -i 's/`bash src\/list.sh \[日付\]` で一覧を出す/`bash src\/list.sh [--room <部屋>] [日付]` で一覧を出す（部屋名は完全一致）/' README.md
cat README.md; echo; bash tools/lint && bash tools/check; echo "check exit=$?"

